'use strict'

const EventEmitter = require('events').EventEmitter

const NOOP = function () {}

const removeWhere = (list, predicate) => {
  const i = list.findIndex(predicate)

  return i === -1 ? undefined : list.splice(i, 1)[0]
}

class IdleItem {
  constructor(client, idleListener, timeoutId) {
    this.client = client
    this.idleListener = idleListener
    this.timeoutId = timeoutId
  }
}

class PendingItem {
  constructor(callback) {
    this.callback = callback
  }
}

function throwOnDoubleRelease() {
  throw new Error('Release called on client which has already been released to the pool.')
}

function promisify(Promise, callback) {
  if (callback) {
    return { callback: callback, result: undefined }
  }
  let rej
  let res
  const cb = function (err, client) {
    err ? rej(err) : res(client)
  }
  const result = new Promise(function (resolve, reject) {
    res = resolve
    rej = reject
  }).catch((err) => {
    // replace the stack trace that leads to `TCP.onStreamRead` with one that leads back to the
    // application that created the query
    Error.captureStackTrace(err)
    throw err
  })
  return { callback: cb, result: result }
}

function makeIdleListener(pool, client) {
  return function idleListener(err) {
    err.client = client

    client.removeListener('error', idleListener)
    client.on('error', () => {
      pool.log('additional client error after disconnection due to error', err)
    })
    pool._remove(client)
    // TODO - document that once the pool emits an error
    // the client has already been closed & purged and is unusable
    pool.emit('error', err, client)
  }
}

function assertFunction(value, name) {
  if (value != null && typeof value !== 'function') {
    throw new TypeError(`${name} must be a function`)
  }
}

function hidePassword(options) {
  if (options && 'password' in options) {
    // "hiding" the password so it doesn't show up in stack traces
    // or if the client is console.logged
    Object.defineProperty(options, 'password', {
      configurable: true,
      enumerable: false,
      writable: true,
      value: options.password,
    })
  }
}

function hideSslKey(options) {
  if (options && options.ssl && typeof options.ssl === 'object' && 'key' in options.ssl) {
    // "hiding" the ssl->key so it doesn't show up in stack traces
    // or if the client is console.logged
    Object.defineProperty(options.ssl, 'key', {
      enumerable: false,
    })
  }
}

function validatePoolOptions(options, Client) {
  if (options != null && typeof options !== 'object') {
    throw new TypeError('Pool options must be an object')
  }
  if (Client != null && typeof Client !== 'function') {
    throw new TypeError('Client must be a constructor function')
  }

  const opts = options || {}

  if (opts.Client != null && typeof opts.Client !== 'function') {
    throw new TypeError('options.Client must be a constructor function')
  }
  if (opts.Promise != null && typeof opts.Promise !== 'function') {
    throw new TypeError('options.Promise must be a Promise constructor')
  }
  if (opts.log != null && typeof opts.log !== 'function') {
    throw new TypeError('options.log must be a function')
  }
  if (opts.onConnect != null && typeof opts.onConnect !== 'function') {
    throw new TypeError('options.onConnect must be a function')
  }
  if (opts.verify != null && typeof opts.verify !== 'function') {
    throw new TypeError('options.verify must be a function')
  }
  if (opts.ssl != null && typeof opts.ssl !== 'object') {
    throw new TypeError('options.ssl must be an object')
  }

  ;[
    'max',
    'min',
    'poolSize',
    'maxUses',
    'maxLifetimeSeconds',
    'idleTimeoutMillis',
    'connectionTimeoutMillis',
  ].forEach((key) => {
    const value = opts[key]
    if (value != null && (typeof value !== 'number' || Number.isNaN(value) || value < 0)) {
      throw new TypeError(`Option ${key} must be a non-negative number`)
    }
  })

  if (opts.allowExitOnIdle != null && typeof opts.allowExitOnIdle !== 'boolean') {
    throw new TypeError('options.allowExitOnIdle must be a boolean')
  }
}

class Pool extends EventEmitter {
  constructor(options, Client) {
    super()

    validatePoolOptions(options, Client)

    this.options = Object.assign({}, options)
    hidePassword(this.options)
    hideSslKey(this.options)

    this.options.max = this.options.max || this.options.poolSize || 10
    this.options.min = this.options.min || 0
    this.options.maxUses = this.options.maxUses || Infinity
    this.options.allowExitOnIdle = this.options.allowExitOnIdle || false
    this.options.maxLifetimeSeconds = this.options.maxLifetimeSeconds || 0
    this.log = this.options.log || function () {}
    this.Client = this.options.Client || Client || require('pg').Client
    this.Promise = this.options.Promise || global.Promise

    if (typeof this.options.idleTimeoutMillis === 'undefined') {
      this.options.idleTimeoutMillis = 10000
    }

    this._clients = []
    this._idle = []
    this._expired = new WeakSet()
    this._pendingQueue = []
    this._endCallback = undefined
    this.ending = false
    this.ended = false
  }

  _promiseTry(f) {
    const Promise = this.Promise
    if (typeof Promise.try === 'function') {
      return Promise.try(f)
    }
    return new Promise((resolve) => resolve(f()))
  }

  _isFull() {
    return this._clients.length >= this.options.max
  }

  _isAboveMin() {
    return this._clients.length > this.options.min
  }

  _pulseQueue() {
    this.log('pulse queue')
    if (this.ended) {
      this.log('pulse queue ended')
      return
    }
    if (this.ending) {
      this.log('pulse queue on ending')
      this._removeIdleClients()
      if (!this._clients.length) {
        this.ended = true
        this._endCallback()
      }
      return
    }

    // if we don't have any waiting, do nothing
    if (!this._pendingQueue.length) {
      this.log('no queued requests')
      return
    }
    // if we don't have any idle clients and we have no more room do nothing
    if (!this._idle.length && this._isFull()) {
      return
    }
    const pendingItem = this._pendingQueue.shift()
    if (this._idle.length) {
      const idleItem = this._idle.pop()
      clearTimeout(idleItem.timeoutId)
      const client = idleItem.client
      if (client.ref) {
        client.ref()
      }
      const idleListener = idleItem.idleListener

      return this._acquireClient(client, pendingItem, idleListener, false)
    }
    if (!this._isFull()) {
      return this.newClient(pendingItem)
    }
    throw new Error('unexpected condition')
  }

  _removeIdleClients() {
    this._idle.slice().forEach((item) => this._remove(item.client))
  }

  _remove(client, callback) {
    const removed = removeWhere(this._idle, (item) => item.client === client)

    if (removed !== undefined) {
      clearTimeout(removed.timeoutId)
    }

    this._clients = this._clients.filter((c) => c !== client)
    const context = this

    if (typeof client.end !== 'function') {
      process.nextTick(() => {
        context.emit('remove', client)
        if (typeof callback === 'function') {
          callback()
        }
      })
      return
    }

    client.end((endErr) => {
      if (endErr) {
        context.log('error ending client', endErr)
      }
      context.emit('remove', client)
      if (typeof callback === 'function') {
        callback()
      }
    })
  }

  _removeAndPulse(client) {
    return this._remove(client, this._pulseQueue.bind(this))
  }

  _failPending(pendingItem, err) {
    if (!pendingItem.timedOut) {
      pendingItem.callback(err, undefined, NOOP)
    }
  }

  _removeAfterFailure(client, pendingItem, err) {
    this._remove(client, () => {
      this._pulseQueue()
      this._failPending(pendingItem, err)
    })
  }

  _createPendingItem(callback, useTimeout) {
    if (!useTimeout) {
      return new PendingItem(callback)
    }

    let tid
    const queueCallback = (err, res, done) => {
      clearTimeout(tid)
      callback(err, res, done)
    }
    const pendingItem = new PendingItem(queueCallback)

    // set connection timeout on checking out an existing client
    tid = setTimeout(() => {
      // remove the callback from pending waiters because
      // we're going to call it with a timeout error
      removeWhere(this._pendingQueue, (i) => i.callback === queueCallback)
      pendingItem.timedOut = true
      callback(new Error('timeout exceeded when trying to connect'))
    }, this.options.connectionTimeoutMillis)

    if (tid.unref) {
      tid.unref()
    }

    return pendingItem
  }

  _startConnectionTimeout(client, onTimeout) {
    if (!this.options.connectionTimeoutMillis) {
      return undefined
    }

    return setTimeout(() => {
      this.log('ending client due to timeout')
      if (client.connection) {
        client.connection.stream.destroy()
      } else if (!client.isConnected()) {
        // force kill the node driver, and let libpq do its teardown
        client.end()
      }
      if (typeof onTimeout === 'function') {
        onTimeout()
      }
    }, this.options.connectionTimeoutMillis)
  }

  connect(cb) {
    assertFunction(cb, 'connect callback')

    if (this.ending) {
      const err = new Error('Cannot use a pool after calling end on the pool')
      return cb ? cb(err) : this.Promise.reject(err)
    }

    const response = promisify(this.Promise, cb)
    const result = response.result

    // if we don't have to connect a new client, don't do so
    if (this._isFull() || this._idle.length) {
      // if we have idle clients schedule a pulse immediately
      if (this._idle.length) {
        process.nextTick(() => this._pulseQueue())
      }

      const pendingItem = this._createPendingItem(
        response.callback,
        this.options.connectionTimeoutMillis > 0
      )
      this._pendingQueue.push(pendingItem)
      return result
    }

    this.newClient(new PendingItem(response.callback))

    return result
  }

  newClient(pendingItem) {
    const client = new this.Client(this.options)
    this._clients.push(client)
    const idleListener = makeIdleListener(this, client)

    this.log('checking client timeout')

    let timeoutHit = false
    const tid = this._startConnectionTimeout(client, () => {
      timeoutHit = true
    })

    this.log('connecting new client')
    client.connect((err) => {
      if (tid) {
        clearTimeout(tid)
      }
      client.on('error', idleListener)
      if (err) {
        this.log('client failed to connect', err)
        if (timeoutHit) {
          err = new Error('Connection terminated due to connection timeout', { cause: err })
        }

        // this client won’t be released, so move on immediately
        this._removeAfterFailure(client, pendingItem, err)
        return
      }

      this.log('new client connected')

      if (this.options.onConnect) {
        this._promiseTry(() => this.options.onConnect(client)).then(
          () => {
            this._afterConnect(client, pendingItem, idleListener)
          },
          (hookErr) => {
            this._removeAfterFailure(client, pendingItem, hookErr)
          }
        )
        return
      }

      this._afterConnect(client, pendingItem, idleListener)
    })
  }

  _afterConnect(client, pendingItem, idleListener) {
    if (this.options.maxLifetimeSeconds !== 0) {
      const maxLifetimeTimeout = setTimeout(() => {
        this.log('ending client due to expired lifetime')
        this._expired.add(client)
        const idleIndex = this._idle.findIndex((idleItem) => idleItem.client === client)
        if (idleIndex !== -1) {
          this._acquireClient(
            client,
            new PendingItem((err, client, clientRelease) => clientRelease()),
            idleListener,
            false
          )
        }
      }, this.options.maxLifetimeSeconds * 1000)

      maxLifetimeTimeout.unref()
      client.once('end', () => clearTimeout(maxLifetimeTimeout))
    }

    return this._acquireClient(client, pendingItem, idleListener, true)
  }

  // acquire a client for a pending work item
  _acquireClient(client, pendingItem, idleListener, isNew) {
    if (isNew) {
      this.emit('connect', client)
    }

    this.emit('acquire', client)

    client.release = this._releaseOnce(client, idleListener)

    client.removeListener('error', idleListener)

    if (pendingItem.timedOut) {
      if (isNew && this.options.verify) {
        this.options.verify(client, client.release)
      } else {
        client.release()
      }
      return
    }

    if (isNew && this.options.verify) {
      this.options.verify(client, (err) => {
        if (err) {
          client.release(err)
          return pendingItem.callback(err, undefined, NOOP)
        }

        pendingItem.callback(undefined, client, client.release)
      })
    } else {
      pendingItem.callback(undefined, client, client.release)
    }
  }

  // returns a function that wraps _release and throws if called more than once
  _releaseOnce(client, idleListener) {
    let released = false

    return (err) => {
      if (released) {
        throwOnDoubleRelease()
      }

      released = true
      this._release(client, idleListener, err)
    }
  }

  _shouldRemoveClient(client, err) {
    // TODO(bmc): expose a proper, public interface _queryable and _ending
    return err || this.ending || !client._queryable || client._ending || client._poolUseCount >= this.options.maxUses
  }

  _maybeScheduleIdleTimeout(client) {
    if (!this.options.idleTimeoutMillis || !this._isAboveMin()) {
      return undefined
    }

    const tid = setTimeout(() => {
      if (this._isAboveMin()) {
        this.log('remove idle client')
        this._removeAndPulse(client)
      }
    }, this.options.idleTimeoutMillis)

    if (this.options.allowExitOnIdle && tid.unref) {
      // allow Node to exit if this is all that's left
      tid.unref()
    }

    return tid
  }

  // release a client back to the pool, include an error
  // to remove it from the pool
  _release(client, idleListener, err) {
    client.on('error', idleListener)

    client._poolUseCount = (client._poolUseCount || 0) + 1

    this.emit('release', err, client)

    if (this._shouldRemoveClient(client, err)) {
      if (client._poolUseCount >= this.options.maxUses) {
        this.log('remove expended client')
      }

      return this._removeAndPulse(client)
    }

    const isExpired = this._expired.has(client)
    if (isExpired) {
      this.log('remove expired client')
      this._expired.delete(client)
      return this._removeAndPulse(client)
    }

    const tid = this._maybeScheduleIdleTimeout(client)

    if (this.options.allowExitOnIdle) {
      if (client.unref) {
        client.unref()
      }
    }

    this._idle.push(new IdleItem(client, idleListener, tid))
    this._pulseQueue()
  }

  query(text, values, cb) {
    assertFunction(cb, 'query callback')

    // guard clause against passing a function as the first parameter
    if (typeof text === 'function') {
      const response = promisify(this.Promise, text)
      setImmediate(() => {
        response.callback(new Error('Passing a function as the first parameter to pool.query is not supported'))
      })
      return response.result
    }

    // allow plain text query without values, but callback
    if (typeof values === 'function') {
      cb = values
      values = undefined
    }
    const response = promisify(this.Promise, cb)
    cb = response.callback

    if (text == null) {
      setImmediate(() => {
        cb(new Error('Query text must be provided to pool.query'))
      })
      return response.result
    }

    this.connect((err, client) => {
      if (err) {
        return cb(err)
      }

      let clientReleased = false
      const onError = (err) => {
        if (clientReleased) {
          return
        }
        clientReleased = true
        client.release(err)
        cb(err)
      }

      client.once('error', onError)
      this.log('dispatching query')
      try {
        client.query(text, values, (err, res) => {
          this.log('query dispatched')
          client.removeListener('error', onError)
          if (clientReleased) {
            return
          }
          clientReleased = true
          client.release(err)
          if (err) {
            return cb(err)
          }
          return cb(undefined, res)
        })
      } catch (err) {
        client.release(err)
        return cb(err)
      }
    })
    return response.result
  }

  end(cb) {
    assertFunction(cb, 'end callback')
    this.log('ending')
    if (this.ending) {
      const err = new Error('Called end on pool more than once')
      return cb ? cb(err) : this.Promise.reject(err)
    }
    this.ending = true
    const promised = promisify(this.Promise, cb)
    this._endCallback = promised.callback
    this._pulseQueue()
    return promised.result
  }

  get waitingCount() {
    return this._pendingQueue.length
  }

  get idleCount() {
    return this._idle.length
  }

  get expiredCount() {
    return this._clients.reduce((acc, client) => acc + (this._expired.has(client) ? 1 : 0), 0)
  }

  get totalCount() {
    return this._clients.length
  }
}

module.exports = Pool